/* سکه‌های پرنده در صحنه هم با اسپرایت واقعی (drawCoin در v3_part3) */
(function coinCanvas27() {
  const img = new Image();
  img.onload = () => { window.__coinImg27 = img; };
  img.src = COIN27;
  const _drawCoin = typeof drawCoin === 'function' ? drawCoin : null;
  window.drawCoin = function (c) {
    const im = window.__coinImg27;
    if (!im || !im.complete || !im.naturalWidth) { if (_drawCoin) _drawCoin(c); return; }
    const spin = Math.max(0.18, Math.abs(Math.cos((c.t || 0) * 5)));
    const R = 8.5;                                  /* کمی درشت‌تر از نسخه‌ی قدیمی (۶) */
    const w = R * 2 * spin, h = R * 2;
    ctx.save();
    ctx.translate(c.x, c.y);
    ctx.shadowColor = 'rgba(255,200,80,.75)'; ctx.shadowBlur = 9;
    ctx.drawImage(im, -w / 2, -h / 2, w, h);
    ctx.restore();
  };
})();

