/* ---------- ۲۷-۸) چیدن برجک — UX جدید ----------
   snap به شبکه‌ی ۲۴px + پد زمین (سبز/قرمز) به‌جای بیضی خط‌چین +
   حلقه‌ی برد کم‌رنگ + پالس. drawPlacing در v3_part3 بازنویسی می‌شود. */
(function placing27() {
  if (typeof drawPlacing !== 'function') return;
  const _old = drawPlacing;
  window.drawPlacing = function () {
    if (!state.placing || !canPlay()) return;
    const def = TURRETS[state.placing.type];
    if (!def) { _old(); return; }
    /* snap به شبکه‌ی ۲۴px — «عزیت» تمام شد */
    const gx = Math.round(state.mouse.x / 24) * 24;
    const gy = Math.round((state.mouse.y - 6) / 24) * 24 + 6;
    const ok = placementValid(gx, gy);
    const pulse = 0.75 + 0.25 * Math.sin(animTime * 5);
    ctx.save();
    ctx.translate(gx, gy);
    /* پد زمین — جای بیضی خط‌چین آزاردهنده */
    ctx.fillStyle = ok ? `rgba(80,220,120,${0.14 * pulse})` : `rgba(235,80,70,${0.16 * pulse})`;
    ctx.beginPath(); ctx.ellipse(0, 6, 30, 12, 0, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = ok ? 'rgba(110,225,140,.66)' : 'rgba(235,80,70,.72)';
    ctx.lineWidth = 2; ctx.setLineDash([5, 4]);
    ctx.beginPath(); ctx.ellipse(0, 6, 30, 12, 0, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([]);
    /* حلقه‌ی برد — کم‌رنگ و آرام (قبلاً پررنگ و مزاحم بود) */
    ctx.strokeStyle = ok ? 'rgba(110,225,140,0.26)' : 'rgba(235,80,70,0.28)';
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.ellipse(0, 6, def.range, def.range * 0.32, 0, 0, Math.PI * 2); ctx.stroke();
    ctx.restore();
    /* شبح برجک — همان drawTurret اصلی (هم‌پوشانی دید با زمین با آلفا) */
    ctx.globalAlpha = 0.66;
    drawTurret({ type: state.placing.type, x: gx, y: gy, cd: 9, flash: 0, recoil: 0,
      aim: gx < TOWER.x ? 0 : Math.PI, spin: animTime * 2, hover: false, bob: 0 });
    ctx.globalAlpha = 1;
    /* نشانگر وضعیت بالای شبح */
    ctx.save();
    ctx.translate(gx, gy - 30);
    if (!ok) {
      ctx.strokeStyle = 'rgba(235,80,70,.95)'; ctx.lineWidth = 3.2; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(-7, -7); ctx.lineTo(7, 7); ctx.moveTo(7, -7); ctx.lineTo(-7, 7);
      ctx.stroke();
    } else {
      ctx.fillStyle = `rgba(110,225,140,${0.9 * pulse})`;
      ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'rgba(110,225,140,.5)'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(0, 0, 7.5, 0, Math.PI * 2); ctx.stroke();
    }
    ctx.restore();
    /* نوار راهنمای فارسی نزدیک مکان‌نما */
    ctx.save();
    ctx.font = '600 13px Vazirmatn';
    ctx.textAlign = 'center';
    const txt = ok ? 'برای نصب ضربه بزن' : 'اینجا نمی‌شه';
    const tw = ctx.measureText(txt).width + 26;
    ctx.fillStyle = 'rgba(10,16,34,.85)';
    rr(gx - tw / 2, gy - 84, tw, 22, 9); ctx.fill();
    ctx.fillStyle = ok ? '#9ff0b2' : '#ffb3a6';
    ctx.fillText(txt, gx, gy - 69);
    ctx.restore();
  };
  /* کلیک نصب هم snap شده — handlePlaceClick در v3_part2 */
  const _hpc = typeof handlePlaceClick === 'function' ? handlePlaceClick : null;
  if (_hpc) {
    window.handlePlaceClick = function () {
      if (!state.placing) { _hpc(); return; }
      const gx = Math.round(state.mouse.x / 24) * 24;
      const gy = Math.round((state.mouse.y - 6) / 24) * 24 + 6;
      const ox = state.mouse.x, oy = state.mouse.y;
      state.mouse.x = gx; state.mouse.y = gy;
      try { _hpc(); } finally { state.mouse.x = ox; state.mouse.y = oy; }
    };
  }
})();

/* ---------- ۲۷-۹) دستفروش بعد از گفتگوی استوری ----------
   قبلاً وسط صحبتِ صبحگاهی آرش و ما می‌آمد؛ حالا صبر می‌کند DLG تمام شود. */
(function pedTiming27() {
  if (typeof peddlerRoll !== 'function') return;
  const _roll = peddlerRoll;
  window.peddlerRoll = function (force) {
    if (force) { try { _roll(force); } catch (e) {} return; }   /* دیباگ/تست → فوری */
    const t0 = Date.now();
    const tryRoll = () => {
      const busy = (typeof DLG !== 'undefined' && DLG.active);
      if (busy && Date.now() - t0 < 45000) { setTimeout(tryRoll, 700); return; }
      try { _roll(); } catch (e) {}
    };
    setTimeout(tryRoll, 2600);   /* اول گفتگوی استوری شروع شود */
  };
})();

